import { CommonModule } from '@angular/common';
import { Component } from '@angular/core';

interface Zone {
  id: number;
  name: string;
  status: 'available' | 'occupied' | 'maintenance' | 'closed';
  statusLabel: string;
  client?: string;
}

@Component({
  selector: 'app-area',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './area.component.html',
  styleUrls: ['./area.component.css']
})

export class AreaComponent {


  // Liste des 12 zones avec des statuts variés (disponible, occupé, maintenance, fermé)
  zones: Zone[] = [
    { id: 1, name: 'Zone 1', status: 'available', statusLabel: 'Disponible' },
    { id: 2, name: 'Zone 2', status: 'occupied', statusLabel: 'Occupé', client: 'Abonné Fibre #402' },
    { id: 3, name: 'Zone 3', status: 'maintenance', statusLabel: 'En maintenance' },
    { id: 4, name: 'Zone 4', status: 'available', statusLabel: 'Disponible' },
    { id: 5, name: 'Zone 5', status: 'closed', statusLabel: 'Fermé (Admin)' },
    { id: 6, name: 'Zone 6', status: 'occupied', statusLabel: 'Occupé', client: 'Ligne ADSL #889' },
    { id: 7, name: 'Zone 7', status: 'available', statusLabel: 'Disponible' },
    { id: 8, name: 'Zone 8', status: 'maintenance', statusLabel: 'En maintenance' },
    { id: 9, name: 'Zone 9', status: 'available', statusLabel: 'Disponible' },
    { id: 10, name: 'Zone 10', status: 'occupied', statusLabel: 'Occupé', client: 'HexaPro #120' },
    { id: 11, name: 'Zone 11', status: 'closed', statusLabel: 'Fermé (Admin)' },
    { id: 12, name: 'Zone 12', status: 'available', statusLabel: 'Disponible' }
  ];

  onZoneClick(zone: Zone) {
    console.log('Zone sélectionnée :', zone);
    // Ajoutez ici votre logique d'ouverture de détails ou d'action sur la zone
  }
}
